mapper.update:
update  bonus_pool_archive set state=#{state}

     ,confirm_time=now()

 where settlement_id = #{settlementId}

mapper.select:
select
bonus_pool_id, bonus_desc, order_bonus, custom_bonus, settle_bonus,
`state`, start_time, end_time,settle_type
from bonus_pool_archive

  channel_id = #{channelId}

    and end_time between #{startTime} and #{endTime}


    and settle_bonus between #{startSettleBonus} and #{endSettleBonus}


    and settle_type = #{settleType}


order by end_time desc

SELECT bpa.bonus_pool_id, bpa.activity_id, bpa.activity_name, bpa.settlement_id, bpa.settlement_name, bpa.order_info, bpa.estimated_dividend, bpa.actual_dividend, bpa.pool_participant, bpa.dividend_method, bpa.dividend_cycle, bpa.confirm_time, bpa.bonus_desc, bpa.state from bonus_pool_archive bpa
${ew.sqlSegment}
order by bpa.create_time desc
